package main

import "embed"

// Tray icons for voice conversation: while it runs, the tray icon becomes a
// pictogram of what it is doing (mic = listening, lines = transcribing,
// hourglass = waiting for the reply, speaker = reading it, ! = problem), so the
// state is told by shape at a glance. Generated by build/gen_tray_state_icons.py.
//
//go:embed trayicons/*.png
var trayStateIcons embed.FS

// trayIconFor returns the tray icon for a voice phase; "" and unknown phases
// get the plain app icon.
func trayIconFor(phase string) []byte {
	if phase == "" {
		return trayIcon
	}
	b, err := trayStateIcons.ReadFile("trayicons/" + phase + ".png")
	if err != nil {
		return trayIcon
	}
	return b
}
